import { useId, type ReactElement } from 'react';
import { useTextExpander, type TextExpanderModel } from './useTextExpander';
import './styles.css';

export type Props = { text: string; maxChars: number };

export function Component({ text, maxChars }: Props): ReactElement {
  const previewId: string = useId();
  const model: TextExpanderModel = useTextExpander(text, maxChars);

  return (
    <div data-testid="panel" className="expander-panel">
      <output id={previewId} aria-label="Preview" className="expander-preview">{model.preview}</output>
      {model.canToggle && (
        <button
          type="button"
          aria-expanded={model.expanded}
          aria-controls={previewId}
          onClick={model.toggle}
        >
          {model.expanded ? 'Show less' : 'Show more'}
        </button>
      )}
    </div>
  );
}

